import { list, put } from '@vercel/blob'
import sharp from 'sharp'

export const cacheImageFromUrl = async (
  imageUrl: string,
  cacheKey: string,
): Promise<string> => {
  const extension = 'webp'
  const filename = `thumbnails/${cacheKey}.${extension}`

  const listOfBlobs = await list({
    limit: 1000,
    prefix: 'thumbnails/',
  })

  const existingBlob = listOfBlobs.blobs.find(
    (blob) => blob.pathname === filename,
  )

  if (existingBlob) {
    return existingBlob.url
  }

  try {
    const response = await fetch(imageUrl)
    if (!response.ok) throw new Error('Failed to fetch image')

    const arrayBuffer = await response.arrayBuffer()
    const optimizedBuffer = await sharp(Buffer.from(arrayBuffer))
      .resize(334, 187, { fit: 'cover' })
      .webp({ quality: 80 }) 
      .toBuffer()

    const { url } = await put(filename, optimizedBuffer, {
      access: 'public',
      contentType: 'image/webp',
      cacheControlMaxAge: 86400 * 7,
      allowOverwrite: false,
    })

    return url
  } catch (error) {
    console.error('Image cache error:', error)
    return imageUrl
  }
}

